<script setup>
import { ref, reactive, watch } from 'vue'
import { request } from '../lib/api.js'
const props=defineProps({classroom:{type:Object,required:true},session:{type:Object,default:null},error:{type:String,default:''}})
const emit=defineEmits(['navigate','refresh','deleted'])
const busy=ref(false),failure=ref(''),success=ref(''),tab=ref('materials'),editing=ref(false),addingMaterial=ref(false),editingMaterial=ref(null),editingAviso=ref(null)
const owner=()=>props.session?.role==='educator' && Number(props.classroom.idEducator)===Number(props.session?.id)
const classForm=reactive({name:'',description:'',price:0,coverImageUrl:'',profileImageUrl:''})
const materialForm=reactive({name:'',tipo:'PDF',url:'',descricao:''})
const avisoText=ref('')
const students=ref([])
function resetClass(){Object.assign(classForm,{name:props.classroom.name||'',description:props.classroom.description||'',price:0,coverImageUrl:props.classroom.coverImageUrl||'',profileImageUrl:props.classroom.profileImageUrl||''})}
watch(()=>props.classroom,resetClass,{immediate:true})
const api=(path,options={})=>request(path,{...options,token:props.session?.token})
async function act(path,options={},message='Alterações salvas.'){busy.value=true;failure.value='';success.value='';try{await api(path,options);success.value=message;await emit('refresh',props.classroom.codigo)}catch(e){failure.value=e.message}finally{busy.value=false}}
async function saveClass(){await act(`/turma/${props.classroom.codigo}`,{method:'PUT',body:{...classForm,idEducator:props.session.id}},'Turma atualizada.');editing.value=false}
async function setStatus(e){await act(`/turma/${props.classroom.codigo}/status`,{method:'PATCH',body:{status:e.target.value}},'Status atualizado.')}
async function scheduleDeletion(){if(!window.confirm('Agendar exclusão desta turma?'))return;await act(`/turma/${props.classroom.codigo}`,{method:'DELETE'},'Exclusão agendada.')}
async function cancelDeletion(){await act(`/turma/${props.classroom.codigo}/cancelar-exclusao`,{method:'PATCH'},'Exclusão cancelada.')}
async function saveMaterial(){await act(editingMaterial.value?`/material/${editingMaterial.value}`:'/material/register',{method:editingMaterial.value?'PUT':'POST',body:{...materialForm,turmaCodigo:props.classroom.codigo}},'Material salvo.');addingMaterial.value=false;editingMaterial.value=null}
function editMaterial(item){editingMaterial.value=item.id;addingMaterial.value=true;Object.assign(materialForm,{name:item.name||'',tipo:item.tipo||'PDF',url:item.url||'',descricao:item.descricao||''})}
function newMaterial(){editingMaterial.value=null;addingMaterial.value=true;Object.assign(materialForm,{name:'',tipo:'PDF',url:'',descricao:''})}
async function removeMaterial(item){if(!window.confirm('Excluir este material?'))return;await act(`/material/delete/${item.id}`,{method:'DELETE'},'Material excluído.')}
async function saveAviso(){const value=avisoText.value.trim();if(!value)return;await act(editingAviso.value?`/turma/${props.classroom.codigo}/avisos/${editingAviso.value}`:`/turma/${props.classroom.codigo}/avisos`,{method:editingAviso.value?'PUT':'POST',body:{mensagem:value}},'Aviso publicado.');editingAviso.value=null;avisoText.value=''}
async function removeAviso(item){if(!window.confirm('Excluir este aviso?'))return;await act(`/turma/${props.classroom.codigo}/avisos/${item.id}`,{method:'DELETE'},'Aviso excluído.')}
async function loadStudents(){failure.value='';try{students.value=Array.from(await api(`/turma/${props.classroom.codigo}/students/info`))}catch(e){failure.value=e.message}}
</script>
<template><section class="container workspace">
<div class="workspace-heading"><div><span class="eyebrow">ESPAÇO DA TURMA</span><h1>{{classroom.name}}</h1><p>{{classroom.description}}</p></div><button class="text-button" @click="emit('navigate','dashboard')">← Minhas turmas</button></div>
<p v-if="error||failure" class="message error" role="alert">{{error||failure}}</p><p v-if="success" class="message success" role="status">{{success}}</p>
<div class="class-detail">
<div v-if="classroom.coverImageUrl" class="class-cover" :style="{backgroundImage:'url('+classroom.coverImageUrl+')'}"></div>
<div class="detail-info"><div><small>PROFESSOR</small><strong>{{classroom.educator||'—'}}</strong></div><div><small>ALUNOS</small><strong>{{classroom.nomeAlunos?.length||0}}</strong></div><div><small>MATERIAIS</small><strong>{{classroom.materiais?.length||0}}</strong></div></div>
<div v-if="owner()" class="management-bar"><button class="button outline" @click="editing=!editing">Editar turma</button><label class="status-label">Status <select :value="classroom.status||'ATIVA'" :disabled="busy" @change="setStatus"><option value="ATIVA">Ativa</option><option value="BLOQUEADA">Bloqueada</option><option value="DESATIVADA">Desativada</option></select></label><button v-if="classroom.dataExclusaoAgendada" class="button outline" :disabled="busy" @click="cancelDeletion">Cancelar exclusão</button><button v-else class="text-button destructive" :disabled="busy" @click="scheduleDeletion">Agendar exclusão</button></div>
<p v-if="classroom.dataExclusaoAgendada" class="message error">Exclusão agendada para {{new Date(classroom.dataExclusaoAgendada).toLocaleDateString('pt-BR')}}.</p>
<form v-if="editing&&owner()" class="form-card create-form" @submit.prevent="saveClass"><h2>Editar informações</h2><label>Nome<input v-model.trim="classForm.name" required maxlength="100"></label><label>Descrição<textarea v-model.trim="classForm.description" rows="3"></textarea></label><label>Imagem de capa (URL)<input v-model.trim="classForm.coverImageUrl" type="url"></label><label>Imagem de perfil (URL)<input v-model.trim="classForm.profileImageUrl" type="url"></label><button class="button dark" :disabled="busy">Salvar turma</button></form>
<div class="detail-tabs" role="tablist" aria-label="Conteúdo da turma"><button :class="{active:tab==='materials'}" role="tab" :aria-selected="tab==='materials'" @click="tab='materials'">Materiais</button><button :class="{active:tab==='notices'}" role="tab" :aria-selected="tab==='notices'" @click="tab='notices'">Avisos</button><button :class="{active:tab==='students'}" role="tab" :aria-selected="tab==='students'" @click="tab='students';loadStudents()">Participantes</button></div>
<div v-if="tab==='materials'"><div class="section-toolbar"><p class="section-label">MATERIAIS</p><button v-if="owner()" class="button outline" @click="newMaterial">+ Adicionar material</button></div>
<form v-if="addingMaterial&&owner()" class="form-card create-form" @submit.prevent="saveMaterial"><label>Nome<input v-model.trim="materialForm.name" required maxlength="255"></label><label>Tipo<select v-model="materialForm.tipo"><option>PDF</option><option>VIDEO</option><option>IMAGEM</option></select></label><label>URL do arquivo<input v-model.trim="materialForm.url" type="url" required></label><label>Descrição<textarea v-model.trim="materialForm.descricao" maxlength="500"></textarea></label><div class="actions"><button class="button dark" :disabled="busy">Salvar material</button><button type="button" class="button outline" @click="addingMaterial=false">Cancelar</button></div></form>
<div v-if="classroom.materiais?.length" class="material-list"><div v-for="material in classroom.materiais" :key="material.id" class="material-entry"><a :href="material.url" target="_blank" rel="noopener noreferrer"><span>{{material.tipo}}</span><strong>{{material.name}}</strong><span>↗</span></a><p v-if="material.descricao">{{material.descricao}}</p><div v-if="owner()" class="inline-actions"><button @click="editMaterial(material)">Editar</button><button class="destructive" :disabled="busy" @click="removeMaterial(material)">Excluir</button></div></div></div><p v-else class="empty">Nenhum material publicado nesta turma.</p></div>
<div v-if="tab==='notices'"><div class="section-toolbar"><p class="section-label">AVISOS</p></div><form v-if="owner()" class="form-card create-form" @submit.prevent="saveAviso"><label>{{editingAviso?'Editar aviso':'Publicar aviso'}}<textarea v-model.trim="avisoText" rows="3" required placeholder="Compartilhe uma atualização com os estudantes…"></textarea></label><div class="actions"><button class="button dark" :disabled="busy">{{editingAviso?'Salvar aviso':'Publicar'}}</button><button v-if="editingAviso" type="button" class="button outline" @click="editingAviso=null;avisoText=''">Cancelar</button></div></form><div v-if="classroom.avisos?.length" class="notice-list"><article v-for="aviso in classroom.avisos" :key="aviso.id" class="notice-entry"><p>{{aviso.mensagem}}</p><small>{{aviso.dataCriacao?new Date(aviso.dataCriacao).toLocaleDateString('pt-BR'):''}}</small><div v-if="owner()" class="inline-actions"><button @click="editingAviso=aviso.id;avisoText=aviso.mensagem">Editar</button><button class="destructive" @click="removeAviso(aviso)">Excluir</button></div></article></div><p v-else class="empty">Ainda não há avisos.</p></div>
<div v-if="tab==='students'"><p class="section-label">PARTICIPANTES</p><div v-if="students.length" class="catalog-list"><div v-for="(student,index) in students" :key="student.id||index" class="catalog-row"><span class="class-icon">◉</span><div><strong>{{student.name||student.nome||('Estudante '+(index+1))}}</strong><small v-if="student.email">{{student.email}}</small></div></div></div><p v-else class="empty">Nenhum participante disponível.</p></div>
</div></section></template>